<?php
declare(strict_types=1); namespace App\Http\Controllers\Students;
use App\Http\Controllers\Controller; use App\Http\Requests\Students\{ConfirmStudentImportRequest,UploadStudentImportRequest}; use App\Models\StudentImportBatch; use App\Services\Students\StudentImportService; use Illuminate\Http\{RedirectResponse,Response}; use Illuminate\View\View;
class StudentImportController extends Controller {public function __construct(private StudentImportService $service){}public function form():View{return view('students.import.form',['title'=>'Import Data Siswa']);}public function preview(UploadStudentImportRequest $request):RedirectResponse{$batch=$this->service->preview($request->file('file'),$request->validated('duplicate_strategy'),$request->user());return redirect()->route('students.import.result',$batch)->with('status','File berhasil dibaca. Silakan periksa pratinjau.');}public function confirm(ConfirmStudentImportRequest $request):RedirectResponse{$batch=StudentImportBatch::findOrFail($request->validated('batch_id'));$this->service->confirm($batch,$request->user());return redirect()->route('students.import.result',$batch)->with('status','Import data siswa berhasil diselesaikan.');}public function result(StudentImportBatch $batch):View{abort_unless($batch->user_id===request()->user()->id||request()->user()->hasRole('super-admin'),403);return view('students.import.result',['title'=>'Hasil Import','batch'=>$batch,'rows'=>$batch->rows()->paginate(100)]);}public function errors(StudentImportBatch $batch):Response{abort_unless($batch->user_id===request()->user()->id||request()->user()->hasRole('super-admin'),403);$csv="Nomor Baris,Nama,NISN,NIK,Status,Pesan\n";foreach($batch->rows()->whereIn('status',['invalid','warning'])->get() as $row)$csv.=implode(',',[$row->row_number,'"'.str_replace('"','""',$row->normalized_data['full_name']??'').'"',$row->normalized_data['nisn']??'',$row->normalized_data['nik']??'',$row->status,'"'.implode('; ',$row->messages??[]).'"'])."\n";return response($csv)->header('Content-Type','text/csv')->header('Content-Disposition','attachment; filename="laporan-error-siswa.csv"');}}
